fn solve(n: i8, m: i8) -> (i8, i8) {
    let min_v = n.min(m);
    let max_v = n.max(m);

    // As described: second = min(n, m), first = (n + m - 1) - second = max(n, m) - 1
    // Use i16 for intermediate arithmetic to avoid overflow, then cast back.
    let first_i16 = (max_v as i16) - 1;
    let second_i16 = min_v as i16;

    debug_assert!((-128..=127).contains(&first_i16));
    debug_assert!((-128..=127).contains(&second_i16));

    (first_i16 as i8, second_i16 as i8)
}